import { MakeLogicType, afterMount, kea, listeners, path, reducers } from 'kea'
import { loaders } from 'kea-loaders'
import posthog from 'posthog-js'

import { lemonToast } from 'lib/lemon-ui/LemonToast/LemonToast'
import { getCurrentTeamId } from 'lib/utils/getAppContext'

import {
    errorTrackingSettingsRetrieveSettingsRetrieve,
    errorTrackingSettingsUpdateSettingsPartialUpdate,
} from '../../../generated/api'
import type { ErrorTrackingSettingsApi } from '../../../generated/api.schemas'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface aiFeaturesSettingsLogicValues {
    settings: ErrorTrackingSettingsApi | null
    settingsLoadFailed: boolean
    settingsLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface aiFeaturesSettingsLogicActions {
    loadSettings: () => any
    loadSettingsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadSettingsSuccess: (
        settings: ErrorTrackingSettingsApi,
        payload?: any
    ) => {
        settings: ErrorTrackingSettingsApi
        payload?: any
    }
    setIssueSummariesEnabled: (enabled: boolean) => boolean
    setIssueSummariesEnabledFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    setIssueSummariesEnabledSuccess: (
        settings: ErrorTrackingSettingsApi,
        payload?: boolean
    ) => {
        settings: ErrorTrackingSettingsApi
        payload?: boolean
    }
}

export type aiFeaturesSettingsLogicType = MakeLogicType<aiFeaturesSettingsLogicValues, aiFeaturesSettingsLogicActions>

export const aiFeaturesSettingsLogic = kea<aiFeaturesSettingsLogicType>([
    path([
        'products',
        'error_tracking',
        'scenes',
        'ErrorTrackingConfigurationScene',
        'ai_features',
        'aiFeaturesSettingsLogic',
    ]),

    loaders({
        settings: [
            null as ErrorTrackingSettingsApi | null,
            {
                loadSettings: async () => {
                    return await errorTrackingSettingsRetrieveSettingsRetrieve(getCurrentTeamId().toString())
                },
                setIssueSummariesEnabled: async (enabled: boolean) => {
                    return await errorTrackingSettingsUpdateSettingsPartialUpdate(getCurrentTeamId().toString(), {
                        ai_issue_summaries_enabled: enabled,
                    })
                },
            },
        ],
    }),

    reducers({
        settingsLoadFailed: [
            false,
            {
                loadSettings: () => false,
                loadSettingsFailure: () => true,
            },
        ],
    }),

    listeners({
        setIssueSummariesEnabledSuccess: ({ settings }) => {
            const enabled = Boolean(settings.ai_issue_summaries_enabled)
            // pinned: analytics event name, renaming it breaks dashboards
            posthog.capture('error_tracking_ai_issue_summaries_toggled', { ai_issue_summaries_enabled: enabled })
            lemonToast.success(enabled ? 'Issue summaries turned on' : 'Issue summaries turned off')
        },
        setIssueSummariesEnabledFailure: ({ errorObject }) => {
            lemonToast.error(errorObject?.detail ?? "Couldn't save this setting. Check your connection and try again.")
        },
    }),

    afterMount(({ actions }) => {
        actions.loadSettings()
    }),
])
